import{_ as e}from"./chunks/field-en.BujBbIY0.js";import{_ as a}from"./chunks/table-en.zH8o5mDJ.js";import{_ as r,o,c as s,a2 as n}from"./chunks/framework.DHtetOlu.js";const f=JSON.parse('{"title":"Results","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/results.md","filePath":"en/guide/results.md"}'),i={name:"en/guide/results.md"};function l(d,t,c,h,u,p){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>After solving, the physics shows up under <strong>Results</strong> with the peak |B|. Its <code>+</code> creates views, plots and tables; each one opens as a <strong>tab</strong> in the canvas (the <strong>Drawing</strong> tab stays there).</p><h2 id="field-views" tabindex="-1">Field views <a class="header-anchor" href="#field-views" aria-label="Permalink to &quot;Field views&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>What it shows</th></tr></thead><tbody><tr><td>Field map</td><td>colored surface (</td></tr><tr><td>Interpolated map</td><td>the same with high-order interpolation and subdivision: smooth contours</td></tr><tr><td>Plot over line</td><td>a quantity along a curve of the drawing (B, Bn, Bt, H, A…)</td></tr></tbody></table><p>A view has <strong>layers</strong> (surface, contour, glyphs) that can be hidden, duplicated and dragged in the tree to another view. In the layer properties: quantity, value range, number of lines, colormap, color and arrow spacing.</p><ul><li>Click the <strong>legend</strong> to change its limits; drag it to move it and use the corner handle to resize it.</li><li><strong>Export</strong> (top bar) writes a PNG or JPG of the view.</li></ul><p><img src="'+e+'" alt="|B| map with flux lines" class="shot"></p><h2 id="tables-and-result-variables" tabindex="-1">Tables and result variables <a class="header-anchor" href="#tables-and-result-variables" aria-label="Permalink to &quot;Tables and result variables&quot;">​</a></h2><p>A <strong>Table</strong> collects items, and each item produces named <strong>result variables</strong> that scripts can read (<code>r.result(&quot;name&quot;)</code>).</p><table tabindex="0"><thead><tr><th>Item</th><th>Results</th></tr></thead><tbody><tr><td>Circuits</td><td>current, turns, flux linkage λ, L = λ/I, DC R, DC V and I²R losses of each circuit</td></tr><tr><td>Surface integral</td><td>over the chosen regions: area, volume, ∫A, current, energy, mean B, losses (Joule and iron), <strong>force Fx, Fy and torque</strong></td></tr><tr><td>Line integral</td><td>along a curve: length, flux Φ, magnetomotive force ∫H·dl, ∫B, mean B, <strong>force and torque</strong> (closed contour)</td></tr><tr><td>Formula</td><td>an expression of the other variables (for example <code>0.5*Coil_L*Coil_I^2</code>)</td></tr></tbody></table><p>Each output has an editable name (by default the item prefix plus the quantity, such as <code>S1_fx</code>). Circuit variables are named <code>&lt;circuit&gt;_I</code>, <code>&lt;circuit&gt;_lambda</code>, <code>&lt;circuit&gt;_L</code> and <code>&lt;circuit&gt;_R</code>.</p><p><img src="'+a+'" alt="Circuit table" class="shot"></p><h2 id="force-and-torque" tabindex="-1">Force and torque <a class="header-anchor" href="#force-and-torque" aria-label="Permalink to &quot;Force and torque&quot;">​</a></h2><p>Force is computed with the <strong>Maxwell stress tensor</strong>, in two ways:</p><ul><li><strong>Surface integral</strong> (recommended): select the regions of the body. It uses the weighted tensor, like the FEMM <em>block integral</em>, and only the air elements around the body contribute. It is the most accurate.</li><li><strong>Line integral</strong>: a closed contour in the air around the body.</li></ul><p>Torque is about the origin. In planar problems the values already include the depth.</p><h2 id="transient-and-ac" tabindex="-1">Transient and AC <a class="header-anchor" href="#transient-and-ac" aria-label="Permalink to &quot;Transient and AC&quot;">​</a></h2><p>In transient and AC analysis, the view bar has a <strong>time bar</strong>, ▶ to animate, frames per second and <strong>Export animation (WebM)</strong>. Table items become <strong>curves over time</strong>; in the item properties you can see the table at a chosen instant. The signals of an external circuit show up when you click a component.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>The <strong>Export</strong> button on the top bar exports the active tab: a field view as PNG or JPG, a plot as SVG, PNG, JPG or CSV, and a table as CSV. The animation (WebM) comes from the view bar. See <a href="./files.html#export">Files, import and export</a>.</p>',20)])])}const v=r(i,[["render",l]]);export{f as __pageData,v as default};
